// Package kaab is the official Go client of the Kaabist API.
//
//	c := kaab.New(os.Getenv("KAAB_API_KEY"))
//	job, err := c.Jobs.Create(ctx, body, kaab.WithWait(30))
//
// The types and request builders are generated by oapi-codegen into package client; the services
// (c.Jobs, c.Programs.Versions, …) are generated from sdks/naming.json; this package's hand-written
// part is the transport — the key, retries, idempotency keys, Prefer: wait, errors — and the
// helpers: Jobs.Wait, the list iterators and Programs.PushFromFile.
package kaab

import (
	"context"
	"net/http"
	"os"
	"runtime"
	"strings"
	"time"
)

// DefaultBaseURL is the public API.
const DefaultBaseURL = "https://api.kaab.ist/v1"

const (
	// DefaultTimeout bounds one attempt; a long-poll gets its wait on top.
	DefaultTimeout = 60 * time.Second
	// DefaultMaxRetries is the retries after the first attempt.
	DefaultMaxRetries = 2
)

// Client is the Kaab API. Its fields are the resources of sdks/naming.json.
type Client struct {
	services

	apiKey     string
	baseURL    string
	httpClient *http.Client
	timeout    time.Duration
	maxRetries int
	headers    http.Header
	random     func() float64
	sleep      func(ctx context.Context, d time.Duration) error
}

// Option configures a Client.
type Option func(*Client)

// WithBaseURL points the client at another deployment (KAAB_BASE_URL by default).
func WithBaseURL(url string) Option {
	return func(c *Client) { c.baseURL = strings.TrimRight(url, "/") }
}

// WithHTTPClient sends requests with hc; its redirect policy is replaced so a presigned redirect is
// answered, not followed.
func WithHTTPClient(hc *http.Client) Option {
	return func(c *Client) { c.httpClient = hc }
}

// WithTimeout bounds each attempt.
func WithTimeout(d time.Duration) Option {
	return func(c *Client) { c.timeout = d }
}

// WithMaxRetries sets the retries after the first attempt.
func WithMaxRetries(n int) Option {
	return func(c *Client) { c.maxRetries = n }
}

// WithHeader adds a header to every request.
func WithHeader(name, value string) Option {
	return func(c *Client) { c.headers.Add(name, value) }
}

// withRandom and withSleep are for tests: the jitter source and the delay between attempts.
func withRandom(f func() float64) Option { return func(c *Client) { c.random = f } }
func withSleep(f func(ctx context.Context, d time.Duration) error) Option {
	return func(c *Client) { c.sleep = f }
}

// New makes a client for apiKey (KAAB_API_KEY when empty).
func New(apiKey string, opts ...Option) *Client {
	if apiKey == "" {
		apiKey = os.Getenv("KAAB_API_KEY")
	}
	base := os.Getenv("KAAB_BASE_URL")
	if base == "" {
		base = DefaultBaseURL
	}
	c := &Client{
		apiKey:     apiKey,
		baseURL:    strings.TrimRight(base, "/"),
		timeout:    DefaultTimeout,
		maxRetries: DefaultMaxRetries,
		headers:    http.Header{},
		random:     defaultRandom,
		sleep:      sleepContext,
	}
	for _, opt := range opts {
		opt(c)
	}
	hc := http.Client{}
	if c.httpClient != nil {
		hc = *c.httpClient
	}
	hc.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	c.httpClient = &hc
	c.services = newServices(c)
	return c
}

// BaseURL is the API the client talks to.
func (c *Client) BaseURL() string { return c.baseURL }

// serverURL is the base URL with a trailing slash, which oapi-codegen's builders resolve
// operation paths against.
func (c *Client) serverURL() string { return c.baseURL + "/" }

func userAgent() string {
	return "kaabist-sdk-go/" + Version + " " + runtime.Version()
}
